void 私有_发送任务管理项目线程消息(
    const std::string& 逻辑ID,
    const std::string& 名称,
    const std::string& 用途,
    const std::string& 类别,
    const std::string& 所属模块,
    const 枚举_线程生命周期消息事件 事件,
    const std::string& 旧生命周期,
    const std::string& 新生命周期,
    const std::string& 运行状态,
    const std::string& 创建者逻辑ID,
    const std::string& 创建者名称,
    const std::string& 线程池ID,
    const std::string& 线程池名称,
    const std::string& 原因键,
    const std::string& 摘要,
    const bool 健康 = true,
    const bool 正常退出 = false) noexcept
{
    结构_线程生命周期消息 消息{};
    消息.事件类型 = 事件;
    消息.线程逻辑ID = 逻辑ID;
    消息.自动填充当前系统线程ID = 事件 != 枚举_线程生命周期消息事件::创建;
    消息.线程名称 = 名称;
    消息.线程用途 = 用途;
    消息.线程类别 = 类别;
    消息.所属模块 = 所属模块;
    消息.创建者逻辑ID = 创建者逻辑ID;
    消息.创建者名称 = 创建者名称;
    消息.所属线程池ID = 线程池ID;
    消息.所属线程池名称 = 线程池名称;
    消息.旧生命周期状态 = 旧生命周期;
    消息.新生命周期状态 = 新生命周期;
    消息.旧运行状态 = 旧生命周期;
    消息.新运行状态 = 运行状态.empty() ? 新生命周期 : 运行状态;
    消息.是否健康 = 健康;
    消息.是否正常退出 = 正常退出;
    消息.原因键 = 原因键;
    消息.显示摘要 = 摘要;
    (void)发送线程生命周期消息(std::move(消息));
}

