bool 私有_后台worker池运行_已持锁(const 结构_任务界面线程状态& 状态) noexcept
{
    return 状态.后台worker已启动
        && !状态.后台worker停止请求
        && 状态.后台worker自我对象 != nullptr;
}

bool 私有_后台worker池运行() noexcept
{
    auto& 状态 = 私有_界面状态();
    std::lock_guard<std::mutex> 锁(状态.锁);
    return 私有_后台worker池运行_已持锁(状态);
}

bool 私有_任务管理停止请求中_已持锁(
    const 结构_任务界面线程状态& 状态) noexcept
{
    return 状态.后台worker停止请求 || 状态.界面循环停止请求;
}

bool 私有_任务管理停止请求中() noexcept
{
    auto& 状态 = 私有_界面状态();
    std::lock_guard<std::mutex> 锁(状态.锁);
    return 私有_任务管理停止请求中_已持锁(状态);
}

时间戳 私有_计算租约重派退避微秒(std::uint32_t 重试次数) noexcept
{
    if (重试次数 == 0) {
        return 私有_租约重派退避基准微秒;
    }
    auto 退避 = 私有_租约重派退避基准微秒;
    for (std::uint32_t i = 1; i < 重试次数; ++i) {
        if (退避 >= 私有_租约重派退避上限微秒 / 2) {
            return 私有_租约重派退避上限微秒;
        }
        退避 *= 2;
    }
    return std::min(退避, 私有_租约重派退避上限微秒);
}

时间戳 私有_工作项入队时间(
    const 任务管理线程协议::结构_任务工作项& 工作项) noexcept
{
    return 工作项.入队时间 != 0 ? 工作项.入队时间 : 工作项.创建时间;
}

时间戳 私有_工作项最早派发时间(
    const 任务管理线程协议::结构_任务工作项& 工作项) noexcept
{
    return 工作项.最早派发时间 != 0
        ? 工作项.最早派发时间
        : 工作项.创建时间;
}

bool 私有_工作项已到最早派发时间(
    const 任务管理线程协议::结构_任务工作项& 工作项,
    时间戳 now) noexcept
{
    const auto 最早派发时间 = 私有_工作项最早派发时间(工作项);
    return 最早派发时间 == 0
        || now == 0
        || 最早派发时间 <= now;
}

std::string 私有_工作项任务排序键(
    const 任务管理线程协议::结构_任务工作项& 工作项)
{
    const auto* 任务 = reinterpret_cast<const 任务节点*>(工作项.任务信息节点);
    if (!任务) {
        return {};
    }
    const auto 主键 = 任务->获取主键();
    if (!主键.empty()) {
        return 主键;
    }
    return std::to_string(reinterpret_cast<std::uintptr_t>(任务));
}

I64 私有_工作项调度优先级(
    const 任务管理线程协议::结构_任务工作项& 工作项) noexcept
{
    if (工作项.任务控制态.全局优先级 != 0) {
        return 工作项.任务控制态.全局优先级;
    }
    const auto* 任务 = reinterpret_cast<const 任务节点*>(工作项.任务信息节点);
    return 任务
        ? 任务类::读取任务调度优先级(任务)
        : 0;
}

int 私有_工作项阶段排序值(
    const 任务管理线程协议::枚举_任务工作项类型 工作类型) noexcept
{
    using enum 任务管理线程协议::枚举_任务工作项类型;
    switch (工作类型) {
    case 执行:
        return 2;
    case 筹办:
        return 1;
    default:
        return 0;
    }
}

std::string 私有_工作项排序兜底键(
    const 任务管理线程协议::结构_任务工作项& 工作项)
{
    std::ostringstream 输出;
    输出 << 私有_工作项任务排序键(工作项)
        << "#" << 工作项.工作项ID
        << "@入队" << 私有_工作项入队时间(工作项)
        << "@最早" << 私有_工作项最早派发时间(工作项);
    return 输出.str();
}

bool 私有_工作项排序在前(
    const 结构_任务调度队列项& 左,
    const 结构_任务调度队列项& 右,
    时间戳 now)
{
    const bool 左已到最早派发时间 = 私有_工作项已到最早派发时间(左.工作项, now);
    const bool 右已到最早派发时间 = 私有_工作项已到最早派发时间(右.工作项, now);
    if (左已到最早派发时间 != 右已到最早派发时间) {
        return 左已到最早派发时间;
    }
    const I64 左调度优先级 = 私有_工作项调度优先级(左.工作项);
    const I64 右调度优先级 = 私有_工作项调度优先级(右.工作项);
    if (左调度优先级 != 右调度优先级) {
        return 左调度优先级 > 右调度优先级;
    }
    const int 左阶段排序值 = 私有_工作项阶段排序值(左.工作项.工作类型);
    const int 右阶段排序值 = 私有_工作项阶段排序值(右.工作项.工作类型);
    if (左阶段排序值 != 右阶段排序值) {
        return 左阶段排序值 > 右阶段排序值;
    }
    if (左.工作项.重试次数 != 右.工作项.重试次数) {
        return 左.工作项.重试次数 < 右.工作项.重试次数;
    }
    const 时间戳 左最早派发时间 = 私有_工作项最早派发时间(左.工作项);
    const 时间戳 右最早派发时间 = 私有_工作项最早派发时间(右.工作项);
    if (左最早派发时间 != 右最早派发时间) {
        return 左最早派发时间 < 右最早派发时间;
    }
    const 时间戳 左入队时间 = 私有_工作项入队时间(左.工作项);
    const 时间戳 右入队时间 = 私有_工作项入队时间(右.工作项);
    if (左入队时间 != 右入队时间) {
        return 左入队时间 < 右入队时间;
    }
    const std::string 左任务排序键 = 私有_工作项任务排序键(左.工作项);
    const std::string 右任务排序键 = 私有_工作项任务排序键(右.工作项);
    if (左任务排序键 != 右任务排序键) {
        return 左任务排序键 < 右任务排序键;
    }
    return 左.工作项.工作项ID < 右.工作项.工作项ID;
}

void 私有_重排调度队列_已持锁(
    结构_任务界面线程状态& 状态,
    std::deque<结构_任务调度队列项>& 队列,
    时间戳 now,
    const std::string& 原因)
{
    (void)状态;
    (void)原因;
    std::stable_sort(
        队列.begin(),
        队列.end(),
        [now](const 结构_任务调度队列项& 左, const 结构_任务调度队列项& 右) {
            return 私有_工作项排序在前(左, 右, now);
        });
}

std::deque<结构_任务调度队列项>* 私有_选择可派发工作项队列_已持锁(
    结构_任务界面线程状态& 状态,
    时间戳 now) noexcept
{
    const bool 执行可派发 =
        !状态.待执行队列.empty()
        && 私有_工作项已到最早派发时间(
            状态.待执行队列.front().工作项,
            now);
    const bool 筹办可派发 =
        !状态.待筹办队列.empty()
        && 私有_工作项已到最早派发时间(
            状态.待筹办队列.front().工作项,
            now);

    if (执行可派发) {
        return &状态.待执行队列;
    }
    if (筹办可派发) {
        return &状态.待筹办队列;
    }
    return nullptr;
}

bool 私有_弹出可派发工作项_已持锁(
    结构_任务界面线程状态& 状态,
    时间戳 now,
    结构_任务调度队列项* 输出) noexcept
{
    if (!输出) {
        return false;
    }

    auto 找可派发 = [now](std::deque<结构_任务调度队列项>& 队列) {
        return std::find_if(
            队列.begin(),
            队列.end(),
            [now](const 结构_任务调度队列项& 项) noexcept {
                return 私有_工作项已到最早派发时间(项.工作项, now);
            });
    };

    auto 执行项 = 找可派发(状态.待执行队列);
    auto 筹办项 = 找可派发(状态.待筹办队列);
    const bool 有执行 = 执行项 != 状态.待执行队列.end();
    const bool 有筹办 = 筹办项 != 状态.待筹办队列.end();

    if (!有执行 && !有筹办) {
        return false;
    }

    if (有执行) {
        *输出 = std::move(*执行项);
        状态.待执行队列.erase(执行项);
        return true;
    }

    *输出 = std::move(*筹办项);
    状态.待筹办队列.erase(筹办项);
    return true;
}

std::uint64_t 私有_等待工作项总数(
    const 结构_任务界面线程状态& 状态) noexcept
{
    return static_cast<std::uint64_t>(
        状态.待筹办队列.size() + 状态.待执行队列.size());
}

bool 私有_worker池大小有效(std::uint64_t worker数量) noexcept
{
    return worker数量 >= 任务管理线程协议::任务管理工作线程池最小大小_常量
        && worker数量 <= 任务管理线程协议::任务管理工作线程池最大大小_常量;
}

void 私有_刷新参数快照_已持锁(结构_任务界面线程状态& 状态) noexcept
{
    状态.快照.任务管理工作线程池默认大小 =
        任务管理线程协议::任务管理工作线程池默认大小_常量;
    状态.快照.任务管理工作线程池最小大小 =
        任务管理线程协议::任务管理工作线程池最小大小_常量;
    状态.快照.任务管理工作线程池最大大小 =
        任务管理线程协议::任务管理工作线程池最大大小_常量;
    状态.快照.任务管理工作线程池当前有效大小 =
        状态.运行参数.任务管理工作线程池当前有效大小;
    状态.快照.任务管理工作线程池待保存大小 =
        状态.运行参数.任务管理工作线程池待保存大小;
    状态.快照.任务管理工作线程池参数版本 =
        状态.运行参数.任务管理工作线程池参数版本;
    状态.快照.最近参数保存状态 = 状态.运行参数.最近参数保存状态;
    状态.快照.最近参数错误状态 = 状态.运行参数.最近参数错误状态;
    状态.快照.最近参数应用状态 = 状态.运行参数.最近参数应用状态;
}

void 私有_刷新队列快照_已持锁(结构_任务界面线程状态& 状态) noexcept
{
    状态.快照.当前等待工作项数 = 私有_等待工作项总数(状态);
    状态.快照.当前状态提交待确认项数 =
        static_cast<std::uint64_t>(状态.状态提交待确认队列.size());
    状态.快照.当前待筹办工作项数 =
        static_cast<std::uint64_t>(状态.待筹办队列.size());
    状态.快照.当前待执行工作项数 =
        static_cast<std::uint64_t>(状态.待执行队列.size());
    状态.快照.当前完成工作项数 =
        static_cast<std::uint64_t>(状态.完成队列.size());
    状态.快照.当前死信工作项数 =
        static_cast<std::uint64_t>(状态.死信队列.size());
    状态.快照.当前在途工作项数 =
        static_cast<std::uint64_t>(状态.在途工作项索引.size());
    状态.快照.当前任务状态快照数 =
        static_cast<std::uint64_t>(状态.任务状态快照表.size());
    状态.快照.当前等待任务索引数 =
        static_cast<std::uint64_t>(状态.等待任务索引.size());
    状态.快照.当前挂起任务索引数 =
        static_cast<std::uint64_t>(状态.挂起任务索引.size());
    auto 刷新头部诊断 = [](const std::deque<结构_任务调度队列项>& 队列,
                         std::string& 头部任务主键,
                         I64& 头部优先级,
                         std::string& 头部兜底键) {
        if (队列.empty()) {
            头部任务主键.clear();
            头部优先级 = 0;
            头部兜底键.clear();
            return;
        }
        const auto& 工作项 = 队列.front().工作项;
        头部任务主键 = 私有_工作项任务排序键(工作项);
        头部优先级 = 私有_工作项调度优先级(工作项);
        头部兜底键 = 私有_工作项排序兜底键(工作项);
    };
    刷新头部诊断(
        状态.待筹办队列,
        状态.快照.待筹办队列头部任务主键,
        状态.快照.待筹办队列头部优先级,
        状态.快照.待筹办队列头部排序兜底键);
    刷新头部诊断(
        状态.待执行队列,
        状态.快照.待执行队列头部任务主键,
        状态.快照.待执行队列头部优先级,
        状态.快照.待执行队列头部排序兜底键);
    状态.快照.后台worker池运行 = 私有_后台worker池运行_已持锁(状态);
    状态.快照.后台worker线程数 =
        static_cast<std::uint64_t>(状态.后台worker线程.size());
    私有_刷新参数快照_已持锁(状态);
}

void 私有_刷新状态提交确认快照_已持锁(
    结构_任务界面线程状态& 状态,
    const 结构_任务状态提交确认令牌& 令牌,
    const std::string& 确认状态) noexcept
{
    私有_刷新队列快照_已持锁(状态);
    状态.快照.最近状态提交确认ID = 令牌.确认ID;
    状态.快照.最近状态提交确认任务主键 = 令牌.任务主键;
    状态.快照.最近状态提交确认状态 = 确认状态;
    状态.快照.最近工作项ID = 令牌.工作项ID;
    if (!令牌.任务主键.empty()) {
        状态.快照.最近任务主键 = 令牌.任务主键;
    }
    if (令牌.目标状态 != 枚举_任务状态::未定义) {
        状态.快照.最近任务状态 = 私有_任务状态文本(令牌.目标状态);
    }
}

std::deque<结构_任务调度队列项>* 私有_选择工作项队列(
    结构_任务界面线程状态& 状态,
    const 任务管理线程协议::枚举_任务工作项类型 工作类型) noexcept
{
    using enum 任务管理线程协议::枚举_任务工作项类型;
    switch (工作类型) {
    case 筹办:
        return &状态.待筹办队列;
    case 执行:
        return &状态.待执行队列;
    default:
        return nullptr;
    }
}

时间戳 私有_时间(时间戳 now) noexcept
{
    return now != 0 ? now : 结构体_时间戳::当前_微秒();
}

std::uint64_t 私有_耗时微秒(时间戳 开始, 时间戳 结束) noexcept
{
    return 结束 >= 开始
        ? static_cast<std::uint64_t>(结束 - 开始)
        : 0;
}

std::string 私有_安全主键(const 任务节点* 节点)
{
    return 节点 ? 节点->获取主键() : std::string{};
}

std::string 私有_安全主键(const 需求节点* 节点)
{
    return 节点 ? 节点->获取主键() : std::string{};
}

std::string 私有_安全主键(const 存在节点类* 节点)
{
    return 节点 ? 节点->获取主键() : std::string{};
}

std::string 私有_任务状态文本(const 枚举_任务状态 状态)
{
    switch (状态) {
    case 枚举_任务状态::未启动: return "未启动";
    case 枚举_任务状态::运行中: return "运行中";
    case 枚举_任务状态::挂起: return "挂起";
    case 枚举_任务状态::完成: return "完成";
    case 枚举_任务状态::已结算: return "已结算";
    case 枚举_任务状态::失败: return "失败";
    case 枚举_任务状态::取消: return "取消";
    case 枚举_任务状态::超时: return "超时";
    case 枚举_任务状态::就绪: return "就绪";
    case 枚举_任务状态::执行中: return "执行中";
    case 枚举_任务状态::筹办中: return "筹办中";
    case 枚举_任务状态::排队中: return "排队中";
    case 枚举_任务状态::等待中: return "等待中";
    case 枚举_任务状态::无法执行: return "无法执行";
    case 枚举_任务状态::待重筹办: return "待重筹办";
    case 枚举_任务状态::未定义:
    default:
        return "未定义";
    }
}

std::string 私有_任务调度键(const 任务节点* 任务)
{
    if (!任务) {
        return {};
    }
    const auto 主键 = 任务->获取主键();
    if (!主键.empty()) {
        return 主键;
    }
    return std::to_string(reinterpret_cast<std::uintptr_t>(任务));
}

bool 私有_工作项租约仍有效(
    const 任务管理线程协议::结构_任务工作项& 工作项,
    时间戳 now) noexcept
{
    return 工作项.租约截止时间 == 0
        || now == 0
        || now <= 工作项.租约截止时间;
}

bool 私有_工作项状态版本可合并(
    const 任务管理线程协议::结构_任务工作项& 已有工作项,
    const 任务管理线程协议::结构_任务工作项& 新工作项) noexcept
{
    if (已有工作项.状态版本 != 0 && 新工作项.状态版本 != 0) {
        return 已有工作项.状态版本 == 新工作项.状态版本;
    }
    return 已有工作项.工作项ID != 0
        && 已有工作项.工作项ID == 新工作项.工作项ID;
}

bool 私有_尝试合并等价等待工作项_已持锁(
    结构_任务界面线程状态& 状态,
    std::deque<结构_任务调度队列项>& 队列,
    const char* 队列名,
    const 任务管理线程协议::结构_任务工作项& 新工作项,
    时间戳 now,
    std::uint64_t* 输出已有工作项ID = nullptr) noexcept
{
    const auto* 新任务 =
        reinterpret_cast<const 任务节点*>(新工作项.任务信息节点);
    const auto 新任务主键 = 私有_任务调度键(新任务);
    if (新任务主键.empty()
        || 新工作项.工作类型 == 任务管理线程协议::枚举_任务工作项类型::未定义) {
        return false;
    }

    for (auto& 已有项 : 队列) {
        auto& 已有工作项 = 已有项.工作项;
        const auto* 已有任务 =
            reinterpret_cast<const 任务节点*>(已有工作项.任务信息节点);
        if (私有_任务调度键(已有任务) != 新任务主键
            || 已有工作项.工作类型 != 新工作项.工作类型
            || !私有_工作项状态版本可合并(已有工作项, 新工作项)
            || !私有_工作项租约仍有效(已有工作项, now)) {
            continue;
        }

        const auto 新最早派发时间 = 私有_工作项最早派发时间(新工作项);
        const auto 旧最早派发时间 = 私有_工作项最早派发时间(已有工作项);
        if (新最早派发时间 != 0) {
            已有工作项.最早派发时间 = 旧最早派发时间 == 0
                ? 新最早派发时间
                : std::max(旧最早派发时间, 新最早派发时间);
        }
        if (输出已有工作项ID) {
            *输出已有工作项ID = 已有工作项.工作项ID;
        }
        私有_重排调度队列_已持锁(
            状态,
            队列,
            now,
            std::string("合并等价等待工作项 | 队列=")
                + (队列名 ? 队列名 : "等待队列")
                + " | 任务=" + 新任务主键);
        状态.快照.最近工作项ID = 已有工作项.工作项ID;
        状态.快照.最近任务主键 = 新任务主键;
        return true;
    }
    return false;
}

void 私有_清理执行前许可工作项状态_已持锁(
    结构_任务界面线程状态& 状态,
    const 任务管理线程协议::结构_任务工作项& 工作项) noexcept;

std::size_t 私有_注册外设观察执行前许可免审批默认集(时间戳 now) noexcept
{
    std::lock_guard<std::mutex> 注册锁(私有_外设观察执行前许可默认集注册锁);
    {
        auto& 状态 = 私有_界面状态();
        std::lock_guard<std::mutex> 锁(状态.锁);
        if (状态.外设观察执行前许可默认集已注册) {
            return 5;
        }
    }

    auto* 自我存在 = 世界树.自我指针;
    if (!自我存在) {
        项目运行日志(
            "任务管理界面线程/外设观察执行前许可免审批默认集注册延后 | 原因=缺少当前自我存在");
        return 0;
    }

    const 枚举_本能方法ID 外设观察免审批默认方法[] = {
        枚举_本能方法ID::自我_验证外设观察像素簇候选,
        枚举_本能方法ID::自我_识别外设观察材料,
        枚举_本能方法ID::自我_扫描当前场景,
        枚举_本能方法ID::自我_跟踪指定存在,
        枚举_本能方法ID::提交_当前观察范围可观测单位存在对应事实,
    };

    std::size_t 已注册 = 0;
    for (const auto 本能ID : 外设观察免审批默认方法) {
        auto* 方法 = 本能方法类::查找或创建本能方法首节点(
            自我存在,
            本能ID,
            now);
        if (!方法) {
            项目运行错误日志(
                "任务管理界面线程/外设观察执行前许可免审批默认集注册失败"
                " | 本能ID=" + std::to_string(static_cast<std::uint32_t>(本能ID))
                + " | 原因=方法首节点缺失");
            continue;
        }

        const auto 方法主键 = 方法->获取主键();
        if (方法主键.empty()) {
            项目运行错误日志(
                "任务管理界面线程/外设观察执行前许可免审批默认集注册失败"
                " | 本能ID=" + std::to_string(static_cast<std::uint32_t>(本能ID))
                + " | 原因=方法主键为空");
            continue;
        }

        bool 新增 = false;
        {
            auto& 状态 = 私有_界面状态();
            std::lock_guard<std::mutex> 锁(状态.锁);
            新增 = 状态.执行前许可免审批方法白名单.insert(方法主键).second;
        }
        ++已注册;
        项目运行日志(
            "任务管理界面线程/注册外设观察执行前许可免审批默认集方法"
            " | 本能ID=" + std::to_string(static_cast<std::uint32_t>(本能ID))
            + " | 方法=" + 方法主键
            + " | 新增=" + std::to_string(新增 ? 1 : 0));
    }

    项目运行日志(
        "任务管理界面线程/外设观察执行前许可免审批默认集注册完成"
        " | 注册数量=" + std::to_string(已注册));
    if (已注册 == (sizeof(外设观察免审批默认方法) / sizeof(外设观察免审批默认方法[0]))) {
        auto& 状态 = 私有_界面状态();
        std::lock_guard<std::mutex> 锁(状态.锁);
        状态.外设观察执行前许可默认集已注册 = true;
    }
    return 已注册;
}

void 私有_同步等待挂起索引_已持锁(
    结构_任务界面线程状态& 状态,
    const 结构_调度任务状态快照& 快照)
{
    if (快照.任务主键.empty()) {
        return;
    }

    状态.等待任务索引.erase(快照.任务主键);
    状态.挂起任务索引.erase(快照.任务主键);

    if (快照.任务状态 != 枚举_任务状态::等待中
        && 快照.任务状态 != 枚举_任务状态::挂起) {
        return;
    }

    结构_等待挂起任务索引记录 记录{};
    记录.任务主键 = 快照.任务主键;
    记录.任务状态 = 快照.任务状态;
    记录.状态版本 = 快照.状态版本;
    记录.最近工作项ID = 快照.最近工作项ID;
    记录.更新时间 = 快照.更新时间;

    if (快照.任务状态 == 枚举_任务状态::等待中) {
        状态.等待任务索引[快照.任务主键] = std::move(记录);
    } else {
        状态.挂起任务索引[快照.任务主键] = std::move(记录);
    }
}

const char* 私有_请求类型文本(
    const 任务管理线程协议::枚举_任务管理请求类型 类型) noexcept
{
    using enum 任务管理线程协议::枚举_任务管理请求类型;
    switch (类型) {
    case 发起任务: return "发起任务";
    case 调度任务: return "调度任务";
    case 重筹办任务: return "重筹办任务";
    case 等待任务: return "等待任务";
    case 取消任务: return "取消任务";
    case 更新权重: return "更新权重";
    case 同步回执: return "同步回执";
    default: return "未定义";
    }
}

任务管理线程协议::枚举_任务管理请求类型 私有_归一请求类型(
    const 任务管理线程协议::结构_任务治理请求& 请求) noexcept
{
    if (请求.请求类型 != 任务管理线程协议::枚举_任务管理请求类型::未定义) {
        if (!请求.任务信息节点
            && 请求.来源需求
            && 请求.允许创建任务信息节点
            && 请求.请求类型 == 任务管理线程协议::枚举_任务管理请求类型::调度任务) {
            return 任务管理线程协议::枚举_任务管理请求类型::发起任务;
        }
        return 请求.请求类型;
    }
    if (!请求.任务信息节点 && 请求.来源需求 && 请求.允许创建任务信息节点) {
        return 任务管理线程协议::枚举_任务管理请求类型::发起任务;
    }
    return 任务管理线程协议::枚举_任务管理请求类型::调度任务;
}

std::string 私有_构造任务治理幂等键(
    const 任务管理线程协议::结构_任务治理请求& 请求)
{
    const auto 类型 = 私有_归一请求类型(请求);
    auto* 任务 = reinterpret_cast<const 任务节点*>(请求.任务信息节点);
    auto* 需求 = reinterpret_cast<const 需求节点*>(请求.来源需求);
    std::ostringstream 输出;
    输出 << "请求类型值=" << static_cast<int>(类型);
    if (类型 == 任务管理线程协议::枚举_任务管理请求类型::发起任务) {
        输出 << "|需求=" << 私有_安全主键(需求);
        return 输出.str();
    }
    输出 << "|任务=" << 私有_安全主键(任务);
    if (需求) {
        输出 << "|需求=" << 私有_安全主键(需求);
    }
    if (类型 == 任务管理线程协议::枚举_任务管理请求类型::调度任务 && 任务) {
        输出 << "|状态=" << static_cast<int>(任务类::读取任务状态(任务))
            << "|阶段=" << static_cast<int>(任务类::读取任务当前阶段(任务))
            << "|运行=" << 任务类::读取任务运行次数(任务)
            << "|权重=" << 任务类::读取任务权重版本号(任务);
    }
    if (请求.请求ID != 0
        && 类型 == 任务管理线程协议::枚举_任务管理请求类型::同步回执) {
        输出 << "|请求=" << 请求.请求ID;
    }
    return 输出.str();
}

const 语素入口节点类* 私有_任务语义特征词(const char* 名称) noexcept
{
    return 名称 ? 语素集.添加信息入口词(名称, 枚举_信息入口类型::特征模板入口) : nullptr;
}

enum class 枚举_外设观察需求口径_任务管理 : std::uint8_t {
    未映射 = 0,
    识别 = 1,
    扫描 = 2,
    跟踪 = 3,
    观察验证 = 4,
};

const char* 私有_外设观察需求口径文本_任务管理(
    枚举_外设观察需求口径_任务管理 口径) noexcept
{
    switch (口径) {
    case 枚举_外设观察需求口径_任务管理::识别: return "识别";
    case 枚举_外设观察需求口径_任务管理::扫描: return "扫描";
    case 枚举_外设观察需求口径_任务管理::跟踪: return "跟踪";
    case 枚举_外设观察需求口径_任务管理::观察验证: return "观察验证";
    case 枚举_外设观察需求口径_任务管理::未映射:
    default:
        return "未映射";
    }
}

bool 私有_目标特征类型等于任务特征_任务管理(
    const 语素入口节点类* 目标特征类型,
    const char* 特征名) noexcept
{
    const auto* 任务特征类型 = 私有_任务语义特征词(特征名);
    return 目标特征类型 && 任务特征类型 && 语素入口同一(目标特征类型, 任务特征类型);
}

I64 私有_方法自我能力值(const 方法类::节点类* 方法) noexcept;

枚举_外设观察需求口径_任务管理 私有_外设观察需求口径_按方法供料要求(
    const 方法类::节点类* 方法) noexcept
{
    if (!方法类::方法是首节点(方法)) {
        return 枚举_外设观察需求口径_任务管理::未映射;
    }

    const auto* 结果项集 = 方法类::方法结果项集(方法);
    if (!结果项集) {
        return 枚举_外设观察需求口径_任务管理::未映射;
    }
    for (const auto& 结果项 : *结果项集) {
        const auto* 结果特征 = 结果项.关系目标特征类型();
        const auto 命中结果特征 = [结果特征](const char* 特征名) noexcept {
            return 私有_目标特征类型等于任务特征_任务管理(结果特征, 特征名);
        };
        if (命中结果特征("外设观察像素簇候选已验证状态")
            || 命中结果特征("外设像素簇候选验证状态")
            || 命中结果特征("外设观察材料可回查状态")) {
            return 枚举_外设观察需求口径_任务管理::观察验证;
        }
        if (命中结果特征("外设观察存在候选确认方案取得状态")
            || 命中结果特征("外设观察存在_自我存在同一性状态")) {
            return 枚举_外设观察需求口径_任务管理::识别;
        }
        if (命中结果特征("当前观察范围可观测单位存在对应事实提交状态")
            || 命中结果特征("当前观察范围有效可观测单位计数事实取得状态")
            || 命中结果特征("当前观察范围可观测单位存在稳定对应事实取得状态")
            || 命中结果特征("稳定对应存在数量明确状态")
            || 命中结果特征("当前观察范围可观测单位存在对应闭合状态")
            || 命中结果特征("扫描可启动状态")) {
            return 枚举_外设观察需求口径_任务管理::识别;
        }
        if (命中结果特征("已识别区域扫描入账状态")
            || 命中结果特征("已归属存在当前特征_基准特征差异状态")
            || 命中结果特征("当前场景扫描组合状态")
            || 命中结果特征("扫描主动因果信息状态")) {
            return 枚举_外设观察需求口径_任务管理::扫描;
        }
        if (命中结果特征("目标存在跟踪状态")
            || 命中结果特征("跟踪预测区间状态")
            || 命中结果特征("跟踪区间迁移状态")
            || 命中结果特征("目标存在丢失状态")
            || 命中结果特征("目标存在重捕获状态")) {
            return 枚举_外设观察需求口径_任务管理::跟踪;
        }
        if (私有_目标特征类型等于任务特征_任务管理(
                结果特征,
                "外设识别结果场景状态")) {
            return 枚举_外设观察需求口径_任务管理::识别;
        }
        if (私有_目标特征类型等于任务特征_任务管理(
                结果特征,
                "外设扫描结果场景状态")) {
            return 枚举_外设观察需求口径_任务管理::扫描;
        }
        if (私有_目标特征类型等于任务特征_任务管理(
                结果特征,
                "外设跟踪结果场景状态")) {
            return 枚举_外设观察需求口径_任务管理::跟踪;
        }
    }
    return 枚举_外设观察需求口径_任务管理::未映射;
}

枚举_外设观察报告类型 私有_外设观察报告类型_按方法供料口径(
    枚举_外设观察需求口径_任务管理 口径) noexcept
{
    switch (口径) {
    case 枚举_外设观察需求口径_任务管理::扫描:
        return 枚举_外设观察报告类型::扫描变化报告;
    case 枚举_外设观察需求口径_任务管理::跟踪:
        return 枚举_外设观察报告类型::跟踪报告;
    case 枚举_外设观察需求口径_任务管理::识别:
    case 枚举_外设观察需求口径_任务管理::观察验证:
        return 枚举_外设观察报告类型::逐簇识别报告;
    case 枚举_外设观察需求口径_任务管理::未映射:
    default:
        return 枚举_外设观察报告类型::未指定;
    }
}

bool 私有_外设观察报告匹配任务当前方法口径(
    任务节点* 任务,
    const 结构_外设观察报告队列项& 报告,
    方法类::节点类** 输出当前方法,
    枚举_外设观察需求口径_任务管理* 输出口径,
    枚举_外设观察报告类型* 输出期望报告类型) noexcept
{
    if (输出当前方法) {
        *输出当前方法 = nullptr;
    }
    if (输出口径) {
        *输出口径 = 枚举_外设观察需求口径_任务管理::未映射;
    }
    if (输出期望报告类型) {
        *输出期望报告类型 = 枚举_外设观察报告类型::未指定;
    }
    if (!任务) {
        return true;
    }

    auto* 当前方法 = reinterpret_cast<方法类::节点类*>(
        任务类::读取任务执行方法(任务));
    if (输出当前方法) {
        *输出当前方法 = 当前方法;
    }
    if (!当前方法) {
        return true;
    }

    const auto 口径 = 私有_外设观察需求口径_按方法供料要求(当前方法);
    if (输出口径) {
        *输出口径 = 口径;
    }
    const auto 期望报告类型 = 私有_外设观察报告类型_按方法供料口径(口径);
    if (输出期望报告类型) {
        *输出期望报告类型 = 期望报告类型;
    }
    if (期望报告类型 == 枚举_外设观察报告类型::未指定) {
        return true;
    }
    return 报告.报告类型 == 期望报告类型;
}

