场景节点类* 私有_推导承载场景(
    自我类& 自我对象,
    const 任务节点* 任务,
    const 需求节点* 需求,
    场景节点类* 请求场景) noexcept
{
    if (请求场景) {
        return 请求场景;
    }
    if (auto* 任务场景 = 任务类::解析任务场景(任务)) {
        return 任务场景;
    }
    if (auto* 需求场景 = 需求类::解析需求场景(需求)) {
        return 需求场景;
    }
    if (auto* 自我内部世界 = 自我对象.确保自我内部世界()) {
        return 自我内部世界;
    }
    return 世界树.自我所在场景;
}

