bool 私有_写观察事实报告ID到任务输入(
    任务节点* 任务,
    std::uint64_t 报告ID,
    时间戳 now) noexcept
{
    if (!任务 || 报告ID == 0) {
        return false;
    }

    const auto 报告可选 = 读取外设观察报告_按ID(报告ID);
    if (报告可选.has_value()) {
        方法类::节点类* 当前方法 = nullptr;
        枚举_外设观察需求口径_任务管理 当前口径 =
            枚举_外设观察需求口径_任务管理::未映射;
        枚举_外设观察报告类型 期望报告类型 =
            枚举_外设观察报告类型::未指定;
        if (!私有_外设观察报告匹配任务当前方法口径(
                任务,
                *报告可选,
                &当前方法,
                &当前口径,
                &期望报告类型)) {
            std::ostringstream 日志;
            日志 << "任务管理界面线程/观察事实报告ID跳过任务输入"
                << " | 原因=报告类型与当前方法供料口径不匹配"
                << " | 任务=" << 任务->获取主键()
                << " | 报告ID=" << 报告ID
                << " | 报告类型=" << 外设观察报告类型文本(报告可选->报告类型)
                << " | 当前方法=" << (当前方法 ? 当前方法->获取主键() : std::string("空"))
                << " | 当前方法供料口径=" << 私有_外设观察需求口径文本_任务管理(当前口径)
                << " | 期望报告类型=" << 外设观察报告类型文本(期望报告类型)
                << " | 写任务虚拟存在=0"
                << " | 写输入场景=0"
                << " | 写输入条件包=0"
                << " | 直接写需求满足=0"
                << " | 直接写世界真值=0";
            项目运行日志(日志.str());
            return false;
        }
    }

    auto* 承载场景 = 任务类::解析任务场景(任务);
    const auto 报告ID值 = static_cast<I64>(报告ID);
    const bool 写任务虚拟存在 = 私有_写任务虚拟存在I64特征(
        任务,
        私有_特征_外设观察报告ID(),
        报告ID值,
        承载场景,
        now);

    std::ostringstream 日志;
    日志 << "任务管理界面线程/观察事实报告ID写入任务输入"
        << " | 任务=" << 任务->获取主键()
        << " | 报告ID=" << 报告ID
        << " | 写任务虚拟存在=" << (写任务虚拟存在 ? 1 : 0)
        << " | 写输入场景=0"
        << " | 写输入条件包=0"
        << " | 输入场景=由下一轮筹办复制"
        << " | 只写任务输入材料引用=1"
        << " | 直接写需求满足=0"
        << " | 直接写世界真值=0";
    项目运行日志(日志.str());
    return 写任务虚拟存在;
}

bool 私有_本能方法首节点匹配(
    方法类::节点类* 方法首节点,
    枚举_本能方法ID 本能ID) noexcept
{
    const auto 动作句柄 = 方法类::方法动作句柄(方法首节点);
    return 方法首节点
        && 本能ID != 枚举_本能方法ID::未定义
        && 方法类::方法是首节点(方法首节点)
        && 动作句柄.类型 == 枚举_动作句柄类型::本能函数ID
        && 动作句柄.本能ID == static_cast<I64>(本能ID);
}

std::atomic<std::uintptr_t>& 私有_状态提交方法缓存_自我存在() noexcept
{
    static std::atomic<std::uintptr_t> s_值{0};
    return s_值;
}

std::atomic<std::uintptr_t>& 私有_状态提交方法缓存_方法首节点() noexcept
{
    static std::atomic<std::uintptr_t> s_值{0};
    return s_值;
}

方法类::节点类* 私有_读取状态提交方法首节点缓存(
    存在节点类* 自我存在,
    枚举_本能方法ID 本能ID) noexcept
{
    if (!自我存在 || 本能ID != 枚举_本能方法ID::自我_提交任务状态变化) {
        return nullptr;
    }
    const auto 自我存在指针 =
        reinterpret_cast<std::uintptr_t>(自我存在);
    if (私有_状态提交方法缓存_自我存在().load(std::memory_order_acquire)
        != 自我存在指针) {
        return nullptr;
    }
    auto* 方法首节点 = reinterpret_cast<方法类::节点类*>(
        私有_状态提交方法缓存_方法首节点().load(std::memory_order_acquire));
    return 私有_本能方法首节点匹配(方法首节点, 本能ID)
        ? 方法首节点
        : nullptr;
}

void 私有_写入状态提交方法首节点缓存(
    存在节点类* 自我存在,
    枚举_本能方法ID 本能ID,
    方法类::节点类* 方法首节点) noexcept
{
    if (!自我存在
        || 本能ID != 枚举_本能方法ID::自我_提交任务状态变化
        || !私有_本能方法首节点匹配(方法首节点, 本能ID)) {
        return;
    }
    私有_状态提交方法缓存_自我存在().store(0, std::memory_order_release);
    私有_状态提交方法缓存_方法首节点().store(
        reinterpret_cast<std::uintptr_t>(方法首节点),
        std::memory_order_release);
    私有_状态提交方法缓存_自我存在().store(
        reinterpret_cast<std::uintptr_t>(自我存在),
        std::memory_order_release);
}

方法类::节点类* 私有_查找或创建状态提交方法首节点(
    任务节点* 任务,
    时间戳 now) noexcept
{
    if (!任务) {
        return nullptr;
    }

    auto* 自我存在 = 世界树.自我指针;
    if (鱼巢_不允许空指(自我存在, "任务管理界面线程/任务状态被动提交/当前自我存在缺失")) {
        项目运行日志("任务管理界面线程/任务状态被动提交 | 缺少当前自我存在，无法定位提交任务状态变化方法");
        return nullptr;
    }

    if (auto* 缓存方法首节点 =
            私有_读取状态提交方法首节点缓存(
                自我存在,
                枚举_本能方法ID::自我_提交任务状态变化)) {
        return 缓存方法首节点;
    }

    auto* 方法首节点 = 本能方法类::查找或创建本能方法首节点(
        自我存在,
        枚举_本能方法ID::自我_提交任务状态变化,
        now);
    私有_写入状态提交方法首节点缓存(
        自我存在,
        枚举_本能方法ID::自我_提交任务状态变化,
        方法首节点);
    if (鱼巢_不允许空指(方法首节点, "任务管理界面线程/任务状态被动提交/提交任务状态变化方法首节点缺失")) {
        std::ostringstream 日志;
        日志 << "任务管理界面线程/任务状态被动提交"
            << " | 任务=" << 任务->获取主键()
            << " | 方法首节点缺失";
        项目运行日志(日志.str());
        return nullptr;
    }
    return 方法首节点;
}

自我动作实现模块::内部模块::结构_任务状态被动提交结果 私有_提交任务状态被动动作(
    任务节点* 任务,
    bool 写入任务状态,
    枚举_任务状态 建议任务状态,
    bool 写入任务阶段,
    枚举_任务阶段 建议任务阶段,
    时间戳 now) noexcept
{
    自我动作实现模块::内部模块::结构_任务状态被动提交请求 请求{};
    请求.提交方法首节点 = 私有_查找或创建状态提交方法首节点(任务, now);
    请求.任务 = 任务;
    请求.写入任务状态 = 写入任务状态;
    请求.建议任务状态 = 建议任务状态;
    请求.写入任务阶段 = 写入任务阶段;
    请求.建议任务阶段 = 建议任务阶段;
    请求.当前时间 = now;
    return 自我动作实现模块::内部模块::提交任务状态被动动作(请求);
}

void 私有_记录调度侧任务状态快照(
    const 任务节点* 任务,
    const 任务管理线程协议::结构_任务工作项* 工作项,
    bool 存在在途工作项,
    时间戳 now,
    const std::string& 原因覆盖) noexcept;

枚举_任务阶段 私有_调度工作项阶段(
    const 任务管理线程协议::枚举_任务工作项类型 工作类型) noexcept
{
    using enum 任务管理线程协议::枚举_任务工作项类型;
    switch (工作类型) {
    case 筹办: return 枚举_任务阶段::筹办;
    case 执行: return 枚举_任务阶段::执行;
    default: return 枚举_任务阶段::未定义;
    }
}

枚举_任务状态 私有_调度工作项入队状态(
    const 任务管理线程协议::枚举_任务工作项类型 工作类型) noexcept
{
    using enum 任务管理线程协议::枚举_任务工作项类型;
    switch (工作类型) {
    case 筹办:
        return 枚举_任务状态::筹办中;
    case 执行:
        return 枚举_任务状态::排队中;
    default:
        return 枚举_任务状态::未定义;
    }
}

bool 私有_提交界面任务状态变化(
    任务节点* 任务,
    枚举_任务状态 新状态,
    枚举_任务阶段 新阶段,
    场景节点类* 请求场景,
    时间戳 now,
    const std::string& 原因) noexcept
{
    if (!任务 || 新状态 == 枚举_任务状态::未定义) {
        return false;
    }
    const auto 提交开始 = 私有_时间(0);
    const std::string 任务主键 = 任务->获取主键();
    std::uint64_t 生命周期锁等待耗时微秒 = 0;
    std::uint64_t 生命周期锁内耗时微秒 = 0;
    std::uint64_t 状态读取耗时微秒 = 0;
    std::uint64_t 终结跳过日志耗时微秒 = 0;
    std::uint64_t 同状态快照耗时微秒 = 0;
    std::uint64_t 准备被动提交耗时微秒 = 0;
    std::uint64_t 执行被动提交耗时微秒 = 0;
    std::uint64_t 同步运行镜像耗时微秒 = 0;
    std::uint64_t 调度快照耗时微秒 = 0;
    std::uint64_t 最终状态读取耗时微秒 = 0;
    std::uint64_t 提交结果日志耗时微秒 = 0;
    枚举_任务状态 旧状态 = 枚举_任务状态::未定义;
    枚举_任务阶段 旧阶段 = 枚举_任务阶段::未定义;

    auto 输出慢提交日志 = [&](
        const char* 结果,
        bool 已提交,
        std::uint64_t 总耗时微秒) {
        if constexpr (!私有_调试日志输出启用()) {
            (void)结果;
            (void)已提交;
            (void)总耗时微秒;
            return;
        }
        if (总耗时微秒 < 10000
            && 生命周期锁等待耗时微秒 < 10000
            && 生命周期锁内耗时微秒 < 10000
            && 准备被动提交耗时微秒 < 10000
            && 执行被动提交耗时微秒 < 10000
            && 调度快照耗时微秒 < 10000
            && 同状态快照耗时微秒 < 10000) {
            return;
        }

        std::string 最慢阶段 = "状态提交锁等待";
        std::uint64_t 最慢阶段耗时微秒 = 生命周期锁等待耗时微秒;
        auto 记录最慢 = [&最慢阶段, &最慢阶段耗时微秒](
            const char* 阶段,
            std::uint64_t 耗时) {
            if (耗时 > 最慢阶段耗时微秒) {
                最慢阶段 = 阶段;
                最慢阶段耗时微秒 = 耗时;
            }
        };
        记录最慢("状态读取", 状态读取耗时微秒);
        记录最慢("终结跳过日志", 终结跳过日志耗时微秒);
        记录最慢("同状态快照", 同状态快照耗时微秒);
        记录最慢("准备被动提交", 准备被动提交耗时微秒);
        记录最慢("执行被动提交", 执行被动提交耗时微秒);
        记录最慢("同步运行镜像", 同步运行镜像耗时微秒);
        记录最慢("调度快照", 调度快照耗时微秒);
        记录最慢("最终状态读取", 最终状态读取耗时微秒);
        记录最慢("提交结果日志", 提交结果日志耗时微秒);

        std::ostringstream 日志;
        日志 << "任务管理界面线程/任务状态提交/阶段耗时"
            << " | 任务=" << 任务主键
            << " | 旧状态=" << 私有_任务状态文本(旧状态)
            << " | 目标状态=" << 私有_任务状态文本(新状态)
            << " | 旧阶段=" << static_cast<int>(旧阶段)
            << " | 目标阶段=" << static_cast<int>(新阶段)
            << " | 结果=" << (结果 ? 结果 : "未知")
            << " | 成功=" << (已提交 ? 1 : 0)
            << " | 总耗时微秒=" << 总耗时微秒
            << " | 最慢阶段=" << 最慢阶段
            << " | 最慢阶段耗时微秒=" << 最慢阶段耗时微秒
            << " | 状态提交锁等待=" << 生命周期锁等待耗时微秒
            << " | 状态提交锁内=" << 生命周期锁内耗时微秒
            << " | 状态读取=" << 状态读取耗时微秒
            << " | 终结跳过日志=" << 终结跳过日志耗时微秒
            << " | 同状态快照=" << 同状态快照耗时微秒
            << " | 准备被动提交=" << 准备被动提交耗时微秒
            << " | 执行被动提交=" << 执行被动提交耗时微秒
            << " | 同步运行镜像=" << 同步运行镜像耗时微秒
            << " | 调度快照=" << 调度快照耗时微秒
            << " | 最终状态读取=" << 最终状态读取耗时微秒
            << " | 提交结果日志=" << 提交结果日志耗时微秒
            << " | 原因=" << 原因;
        项目运行日志(日志.str());
    };

    const auto 生命周期锁等待开始 = 私有_时间(0);
    std::lock_guard<std::mutex> 生命周期锁(私有_任务状态提交互斥());
    生命周期锁等待耗时微秒 =
        私有_耗时微秒(生命周期锁等待开始, 私有_时间(0));
    const auto 生命周期锁内开始 = 私有_时间(0);
    const auto 状态读取开始 = 私有_时间(0);
    旧状态 = 任务类::读取任务状态(任务, 枚举_任务状态::未定义);
    旧阶段 = 任务类::读取任务当前阶段(任务, 枚举_任务阶段::未定义);
    状态读取耗时微秒 =
        私有_耗时微秒(状态读取开始, 私有_时间(0));
    if (任务类::任务状态已终结(旧状态)) {
        const auto 终结跳过日志开始 = 私有_时间(0);
        std::ostringstream 日志;
        日志 << "任务管理界面线程/任务状态提交跳过"
            << " | 任务=" << 任务主键
            << " | 旧状态=" << 私有_任务状态文本(旧状态)
            << " | 目标状态=" << 私有_任务状态文本(新状态)
            << " | 原因=任务已终结，不再由调度消息推进";
        项目运行日志(日志.str());
        终结跳过日志耗时微秒 =
            私有_耗时微秒(终结跳过日志开始, 私有_时间(0));
        const auto 调度快照开始 = 私有_时间(0);
        私有_记录调度侧任务状态快照(任务, nullptr, false, now, 原因);
        调度快照耗时微秒 =
            私有_耗时微秒(调度快照开始, 私有_时间(0));
        生命周期锁内耗时微秒 =
            私有_耗时微秒(生命周期锁内开始, 私有_时间(0));
        输出慢提交日志(
            "任务已终结",
            false,
            私有_耗时微秒(提交开始, 私有_时间(0)));
        return false;
    }

    if (旧状态 == 新状态
        && (新阶段 == 枚举_任务阶段::未定义 || 旧阶段 == 新阶段)) {
        const auto 同状态快照开始 = 私有_时间(0);
        私有_记录调度侧任务状态快照(任务, nullptr, false, now, 原因);
        同状态快照耗时微秒 =
            私有_耗时微秒(同状态快照开始, 私有_时间(0));
        生命周期锁内耗时微秒 =
            私有_耗时微秒(生命周期锁内开始, 私有_时间(0));
        输出慢提交日志(
            "同状态快照",
            true,
            私有_耗时微秒(提交开始, 私有_时间(0)));
        return true;
    }

    const auto 准备被动提交开始 = 私有_时间(0);
    auto* 提交方法首节点 = 私有_查找或创建状态提交方法首节点(任务, now);
    准备被动提交耗时微秒 =
        私有_耗时微秒(准备被动提交开始, 私有_时间(0));
    if (鱼巢_不允许空指(提交方法首节点, "任务管理界面线程/任务状态提交/提交任务状态变化来源方法缺失")) {
        项目运行错误日志(
            "任务管理界面线程/任务状态提交失败"
            " | 任务=" + 任务主键
            + " | 原因=无法定位提交任务状态变化来源方法");
        生命周期锁内耗时微秒 =
            私有_耗时微秒(生命周期锁内开始, 私有_时间(0));
        输出慢提交日志(
            "来源方法缺失",
            false,
            私有_耗时微秒(提交开始, 私有_时间(0)));
        return false;
    }

    const auto 执行被动提交开始 = 私有_时间(0);
    自我动作实现模块::内部模块::结构_任务状态被动提交请求 提交请求{};
    提交请求.提交方法首节点 = 提交方法首节点;
    提交请求.任务 = 任务;
    提交请求.写入任务状态 = true;
    提交请求.建议任务状态 = 新状态;
    提交请求.写入任务阶段 = 新阶段 != 枚举_任务阶段::未定义;
    提交请求.建议任务阶段 = 新阶段;
    提交请求.当前时间 = now;
    const auto 提交结果 =
        自我动作实现模块::内部模块::提交任务状态被动动作(提交请求);
    执行被动提交耗时微秒 =
        私有_耗时微秒(执行被动提交开始, 私有_时间(0));
    const bool 已提交 = 提交结果.已提交;
    const auto 同步运行镜像开始 = 私有_时间(0);
    (void)任务类::同步任务运行镜像特征(任务, 请求场景, now);
    同步运行镜像耗时微秒 =
        私有_耗时微秒(同步运行镜像开始, 私有_时间(0));
    const auto 调度快照开始 = 私有_时间(0);
    私有_记录调度侧任务状态快照(任务, nullptr, false, now, 原因);
    调度快照耗时微秒 =
        私有_耗时微秒(调度快照开始, 私有_时间(0));

    const auto 提交结果日志开始 = 私有_时间(0);
    const auto 最终状态读取开始 = 私有_时间(0);
    const auto 最新状态 = 任务类::读取任务状态(任务, 枚举_任务状态::未定义);
    const auto 最新阶段 = 任务类::读取任务当前阶段(任务, 枚举_任务阶段::未定义);
    最终状态读取耗时微秒 =
        私有_耗时微秒(最终状态读取开始, 私有_时间(0));
    std::ostringstream 日志;
    日志 << "任务管理界面线程/任务状态提交"
        << " | 任务=" << 任务主键
        << " | 旧状态=" << 私有_任务状态文本(旧状态)
        << " | 新状态=" << 私有_任务状态文本(最新状态)
        << " | 旧阶段=" << static_cast<int>(旧阶段)
        << " | 新阶段=" << static_cast<int>(最新阶段)
        << " | 成功=" << (已提交 ? 1 : 0)
        << " | 任务状态动作动态="
        << (提交结果.任务状态动作动态
            ? 提交结果.任务状态动作动态->获取主键()
            : std::string("缺"))
        << " | 原因=" << 原因;
    项目运行日志(日志.str());
    提交结果日志耗时微秒 =
        私有_耗时微秒(提交结果日志开始, 私有_时间(0));
    生命周期锁内耗时微秒 =
        私有_耗时微秒(生命周期锁内开始, 私有_时间(0));
    输出慢提交日志(
        "完整提交",
        已提交,
        私有_耗时微秒(提交开始, 私有_时间(0)));
    return 已提交;
}

方法类::节点类* 私有_工作结果当前方法(
    const 任务管理线程协议::结构_任务工作结果& 工作结果) noexcept
{
    auto* 方法 = 工作结果.治理结果.当前方法;
    if (!方法
        && 工作结果.存在任务筹办情况
        && 工作结果.任务筹办情况.筹办回执.当前方法.指针) {
        方法 = reinterpret_cast<方法类::节点类*>(
            工作结果.任务筹办情况.筹办回执.当前方法.指针);
    }
    if (!方法
        && 工作结果.存在任务执行情况
        && 工作结果.任务执行情况.执行回执.当前方法.指针) {
        方法 = reinterpret_cast<方法类::节点类*>(
            工作结果.任务执行情况.执行回执.当前方法.指针);
    }
    if (!方法
        && 工作结果.存在任务执行情况
        && 工作结果.任务执行情况.执行数据.当前方法) {
        方法 = 工作结果.任务执行情况.执行数据.当前方法;
    }
    if (!方法
        && 工作结果.存在任务推进回执
        && 工作结果.任务推进回执.当前方法.指针) {
        方法 = reinterpret_cast<方法类::节点类*>(
            工作结果.任务推进回执.当前方法.指针);
    }
    if (!方法 && 工作结果.存在方法执行数据) {
        方法 = 工作结果.方法执行数据.当前方法;
    }
    return 方法;
}

const 任务模块::筹办::结构_任务推进回执* 私有_工作结果推进回执(
    const 任务管理线程协议::结构_任务工作结果& 工作结果) noexcept
{
    if (工作结果.存在任务筹办情况
        && 工作结果.任务筹办情况.有效) {
        return &工作结果.任务筹办情况.筹办回执;
    }
    if (工作结果.存在任务执行情况
        && 工作结果.任务执行情况.有效) {
        return &工作结果.任务执行情况.执行回执;
    }
    if (工作结果.存在任务推进回执) {
        return &工作结果.任务推进回执;
    }
    return nullptr;
}

特征节点类* 私有_工作结果方法运行结果(
    const 任务管理线程协议::结构_任务工作结果& 工作结果) noexcept
{
    if (工作结果.存在任务执行情况
        && 工作结果.任务执行情况.方法运行结果) {
        return 工作结果.任务执行情况.方法运行结果;
    }
    if (工作结果.存在任务筹办情况
        && 工作结果.任务筹办情况.方法运行结果) {
        return 工作结果.任务筹办情况.方法运行结果;
    }
    return 工作结果.方法运行结果;
}

场景节点类* 私有_工作结果输出结果场景(
    const 任务管理线程协议::结构_任务工作结果& 工作结果) noexcept
{
    if (工作结果.存在任务执行情况
        && 工作结果.任务执行情况.输出结果场景) {
        return 工作结果.任务执行情况.输出结果场景;
    }
    if (工作结果.存在任务筹办情况
        && 工作结果.任务筹办情况.结果场景) {
        return 工作结果.任务筹办情况.结果场景;
    }
    if (工作结果.存在方法执行数据) {
        return 工作结果.方法执行数据.结果场景;
    }
    return nullptr;
}

存在节点类* 私有_确保任务虚拟存在(
    自我类& 自我对象,
    任务节点* 任务,
    需求节点* 来源需求,
    场景节点类* 请求场景,
    时间戳 now) noexcept
{
    if (!任务) {
        return nullptr;
    }
    auto* 承载场景 = 私有_推导承载场景(自我对象, 任务, 来源需求, 请求场景);
    auto* 任务存在 = 任务类::取或创建_任务虚拟存在(任务, 承载场景);
    if (!任务存在) {
        return nullptr;
    }
    (void)任务类::同步任务节点到虚拟存在(任务, 承载场景, now);
    return 任务存在;
}

bool 私有_用需求初始化任务虚拟存在(
    自我类& 自我对象,
    任务节点* 任务,
    需求节点* 来源需求,
    场景节点类* 请求场景,
    时间戳 now) noexcept
{
    if (!任务 || !来源需求) {
        return false;
    }
    auto* 承载场景 = 私有_推导承载场景(自我对象, 任务, 来源需求, 请求场景);

    auto* 发起存在 = 需求类::解析需求主体(来源需求);
    if (!发起存在) {
        发起存在 = 自我对象.获取自我存在();
    }
    auto* 当前状态 = 需求类::解析需求当前状态(来源需求);
    auto* 目标状态 = 需求类::解析需求目标状态(来源需求);
    auto* 作用对象 = 需求类::解析需求目标宿主(来源需求);
    auto* 所属上下文 = 需求类::解析需求场景(来源需求);
    if (!所属上下文) {
        所属上下文 = 承载场景;
    }

    bool 任一写入 = false;
    任一写入 = 私有_写任务虚拟存在指针特征(任务, "任务发起存在", 发起存在, 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在指针特征(任务, "任务作用对象", 作用对象, 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在指针特征(任务, "任务所属上下文", 所属上下文, 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在指针特征(任务, "任务当前状态", 当前状态, 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在指针特征(任务, "任务目标状态", 目标状态, 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在指针特征(任务, "任务目标", 目标状态, 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在指针特征(任务, "任务完成条件目标状态", 目标状态, 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在I64特征(任务, "任务满足关系", static_cast<I64>(需求类::读取需求满足关系(来源需求)), 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在I64特征(任务, "任务安全权重", static_cast<I64>(需求类::读取需求安全权重(来源需求)), 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在I64特征(任务, "任务服务权重", static_cast<I64>(需求类::读取需求服务权重(来源需求)), 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在I64特征(任务, "任务综合优先级", static_cast<I64>(需求类::读取需求综合权重(来源需求)), 承载场景, now) || 任一写入;
    任一写入 = 私有_写任务虚拟存在I64特征(任务, "任务语义状态", static_cast<I64>(任务类::读取任务状态(任务, 枚举_任务状态::未启动)), 承载场景, now) || 任一写入;
    return 任一写入;
}

void 私有_绑定任务需求关系(任务节点* 任务, 需求节点* 需求) noexcept
{
    if (!任务 || !需求) {
        return;
    }
    (void)任务类::绑定对应需求(
        任务,
        reinterpret_cast<需求节点类*>(需求));
    (void)需求类::绑定对应任务(需求, reinterpret_cast<任务节点类*>(任务));
}

void 私有_准备任务运行壳(任务节点* 任务, 需求节点* 需求, 时间戳 now) noexcept
{
    if (!任务 || !需求) {
        return;
    }
    auto* 任务场景 = 任务类::解析任务场景(任务);
    if (任务类::读取任务角色(任务) == 枚举_任务角色::未定义) {
        (void)任务类::写入任务角色(
            任务,
            需求->子 ? 枚举_任务角色::需求管理任务 : 枚举_任务角色::需求执行任务,
            任务场景,
            now);
    }
    可解析引用<状态节点类> 目标状态引用{};
    可解析引用<状态节点类> 当前状态引用{};
    (void)需求类::读取需求目标状态引用(需求, 目标状态引用);
    (void)需求类::读取需求当前状态引用(需求, 当前状态引用);
    (void)任务类::写入任务目标状态(任务, 目标状态引用);
    (void)任务类::写入任务实际结果状态(任务, 当前状态引用);
    const auto 基准优先级 = 需求类::读取需求综合权重(需求);
    (void)任务类::写入任务基准优先级(任务, 基准优先级);
    (void)任务类::写入任务调度优先级(
        任务,
        基准优先级 + 任务类::读取任务局部优先级偏移(任务));
    任务类::确保任务初始状态(任务);
}

任务节点* 私有_按需求创建任务并初始化(
    自我类& 自我对象,
    需求节点* 需求,
    任务节点* 上级任务,
    时间戳 now) noexcept
{
    if (!需求) {
        return nullptr;
    }
    auto* 自我存在 = 自我对象.获取自我存在();
    if (!自我存在) {
        return nullptr;
    }
    (void)世界树.确保存在三类根节点(自我存在);
    auto* 世界任务根 = reinterpret_cast<任务节点*>(世界树.获取任务根节点(自我存在));
    if (!世界任务根) {
        return nullptr;
    }

    任务类 任务服务{};
    auto* 原根 = 任务服务.根指针;
    任务服务.根指针 = 世界任务根;
    auto* 任务 = 任务服务.创建任务头结点(
        reinterpret_cast<需求节点类*>(需求),
        上级任务,
        now);
    任务服务.根指针 = 原根;
    if (!任务) {
        return nullptr;
    }

    // 任务管理界面线程是任务域写入入口：创建后立即补运行壳和语义壳。
    私有_绑定任务需求关系(任务, 需求);
    私有_准备任务运行壳(任务, 需求, now);
    auto* 任务场景 = 任务类::解析任务场景(任务);
    auto* 任务存在 = 私有_确保任务虚拟存在(
        自我对象,
        任务,
        需求,
        任务场景,
        now);
    if (任务存在) {
        (void)私有_用需求初始化任务虚拟存在(
            自我对象,
            任务,
            需求,
            任务场景,
            now);
    }
    return 任务;
}

结构_任务根节点 私有_构造任务根节点(
    const 任务管理线程协议::结构_任务治理请求& 请求,
    std::uint64_t 请求ID) noexcept
{
    auto* 任务 = reinterpret_cast<任务节点*>(请求.任务信息节点);
    结构_任务根节点 根节点{};
    根节点.任务根ID = 任务
        ? static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(任务))
        : 请求ID;
    根节点.来源需求指针 = reinterpret_cast<std::uintptr_t>(请求.来源需求);
    根节点.世界任务根指针 = reinterpret_cast<std::uintptr_t>(任务);
    根节点.父任务指针 = 任务 && 任务->父
        ? reinterpret_cast<std::uintptr_t>(任务->父)
        : 0;
    根节点.管理对象任务指针 = reinterpret_cast<std::uintptr_t>(任务);
    根节点.初始授权等级 = 1;
    根节点.只读 = false;
    return 根节点;
}

结构_任务控制态 私有_构造任务控制态(
    const 结构_任务根节点& 根节点,
    const 任务节点* 任务) noexcept
{
    结构_任务控制态 控制态{};
    控制态.任务根ID = 根节点.任务根ID;
    控制态.队列状态 = !任务
        ? 枚举_任务队列状态::等待
        : (任务类::任务状态已终结(任务类::读取任务状态(任务))
            ? 枚举_任务队列状态::已结算
            : 枚举_任务队列状态::可运行);
    控制态.全局优先级 = 任务 ? 任务类::读取任务调度优先级(任务) : 0;
    控制态.绑定工作线程ID = 1;
    return 控制态;
}

结构_任务局部运行态 私有_构造任务局部运行态(
    const 结构_任务根节点& 根节点,
    const 任务节点* 任务) noexcept
{
    结构_任务局部运行态 运行态{};
    运行态.任务根ID = 根节点.任务根ID;
    运行态.当前状态 = !任务
        ? 枚举_任务局部运行状态::等待条件
        : (任务类::任务状态已终结(任务类::读取任务状态(任务))
            ? 枚举_任务局部运行状态::局部完成
            : 枚举_任务局部运行状态::已受理);
    运行态.当前步骤前沿 = reinterpret_cast<std::uintptr_t>(任务);
    return 运行态;
}

